package golang

const streamRequestHTTPConsumer = `package consumer_test
import("bufio";"context";"errors";"io";"net/http";"net/http/httptest";"strings";"sync";"sync/atomic";"testing";"time";sdk "example.test/consumer/api";"example.test/consumer/api/types")
type duplexItems struct{ctx context.Context;release <-chan struct{};index int;closes *atomic.Int32}
func(source *duplexItems)Next()bool{if source.index==2{return false};if source.index==1{select{case <-source.release:case <-source.ctx.Done():return false}};source.index++;return true}
func(source *duplexItems)Item()sdk.EchoNumbersRequestItem{return sdk.EchoNumbersRequestItem{ID:float64(source.index+2)}}
func(source *duplexItems)Err()error{return source.ctx.Err()}
func(source *duplexItems)Close()error{source.closes.Add(1);return nil}
func TestActualBidirectionalHTTPStreams(t *testing.T){
 for _,http2:=range []bool{false,true}{name:="http1";if http2{name="http2"};t.Run(name,func(t *testing.T){
  server:=httptest.NewUnstartedServer(http.HandlerFunc(func(writer http.ResponseWriter,request *http.Request){if http2&&request.ProtoMajor!=2{t.Error("HTTP/2 was not negotiated",request.Proto)};if err:=http.NewResponseController(writer).EnableFullDuplex();err!=nil&&request.ProtoMajor==1{t.Error(err);return};writer.Header().Set("Content-Type","application/x-ndjson");scanner:=bufio.NewScanner(request.Body);for scanner.Scan(){if _,err:=io.WriteString(writer,scanner.Text()+"\n");err!=nil{return};writer.(http.Flusher).Flush()};if err:=scanner.Err();err!=nil&&request.Context().Err()==nil{t.Error(err)}}));server.EnableHTTP2=http2;if http2{server.StartTLS()}else{server.Start()};defer server.Close()
  client,err:=sdk.NewClient(sdk.ClientOptions{BaseURL:server.URL,HTTPClient:server.Client()});if err!=nil{t.Fatal(err)};ctx,cancel:=context.WithTimeout(context.Background(),5*time.Second);defer cancel();release:=make(chan struct{});var closes atomic.Int32
  factory:=func(ctx context.Context)(types.Source[sdk.EchoNumbersRequestItem],error){return &duplexItems{ctx:ctx,release:release,closes:&closes},nil};handle:=client.Operations.EchoNumbers(sdk.EchoNumbersInput{Body:sdk.NewEchoNumbersStreamBody(factory)}).Stream(ctx);defer handle.Close()
  response,err:=handle.Response();if err!=nil{t.Fatal("headers blocked behind the upload",err)};if http2&&response.ProtoMajor!=2{t.Fatal("response protocol",response.Proto)};if !handle.Next()||handle.Item().ID!=3{t.Fatal("first response while upload is blocked",handle.Err())};close(release);if !handle.Next()||handle.Item().ID!=4||handle.Next()||handle.Err()!=nil{t.Fatal("duplex completion",handle.Err())};if closes.Load()!=1{t.Fatal("duplex source close",closes.Load())}
 })}
}
type uploadPipeProtocol struct{maximum *atomic.Int32;failure error;nilReader bool}
func(uploadPipeProtocol)Decode(context.Context,types.StreamReader,types.StreamContext)(types.Source[types.Value],error){return nil,errors.New("unused direction")}
func(protocol uploadPipeProtocol)Encode(ctx context.Context,source types.Source[types.Value],info types.StreamContext)(io.ReadCloser,error){if protocol.maximum!=nil{protocol.maximum.Store(int32(info.MaxFrameBytes))};if protocol.failure!=nil{return nil,protocol.failure};if protocol.nilReader{var reader *uploadPipeReader;return reader,nil};return &uploadPipeReader{ctx:ctx,source:source,maximum:info.MaxFrameBytes},nil}
type uploadPipeReader struct{ctx context.Context;source types.Source[types.Value];maximum int;current *strings.Reader;closed atomic.Bool;once sync.Once;closeErr error}
func(reader *uploadPipeReader)Read(buffer []byte)(int,error){for{if reader.closed.Load(){return 0,io.ErrClosedPipe};if err:=reader.ctx.Err();err!=nil{return 0,err};if reader.current!=nil{count,err:=reader.current.Read(buffer);if count>0{return count,nil};if err!=io.EOF{return count,err};reader.current=nil};if !reader.source.Next(){if err:=reader.source.Err();err!=nil{return 0,err};return 0,io.EOF};data,err:=reader.source.Item().MarshalJSON();if err!=nil{return 0,err};if len(data)+1>reader.maximum{return 0,errors.New("custom frame limit")};reader.current=strings.NewReader(string(data)+"|")}}
func(reader *uploadPipeReader)Close()error{reader.once.Do(func(){reader.closed.Store(true);reader.closeErr=reader.source.Close()});return reader.closeErr}
func TestCustomRequestProtocolAndFailureOwnership(t *testing.T){
 var maximum atomic.Int32;codec:=types.NewStreamCodec[types.Value,types.Value](uploadPipeProtocol{maximum:&maximum},nil);transport:=&requestTransport{inspect:func(request *http.Request)(*http.Response,error){defer request.Body.Close();data,err:=io.ReadAll(request.Body);if err!=nil{return nil,err};if string(data)!="{\"id\":1}|{\"id\":2}|"{t.Error("custom request bytes",string(data))};return emptyRequestResponse(request),nil}};client:=requestClient(t,transport,map[string]types.StreamCodec{"application/vnd.frames":codec});stats:=&requestStats{requireCancel:true};factory:=itemFactory(stats,[]sdk.UploadCustomRequestItem{ {ID:1},{ID:2} });if _,err:=client.Operations.UploadCustom(sdk.UploadCustomInput{Body:factory}).WithOptions(types.RequestOptions{MaxStreamFrameBytes:types.Some(32)}).Do(context.Background());err!=nil{t.Fatal(err)};if maximum.Load()!=32||stats.closes.Load()!=1{t.Fatal("custom context/ownership",maximum.Load(),stats.closes.Load())}
 sentinel:=errors.New("custom encode constructor failed");for _,protocol:=range []uploadPipeProtocol{ {failure:sentinel},{nilReader:true} }{override:=types.NewStreamCodec[types.Value,types.Value](protocol,nil);failureStats:=&requestStats{requireCancel:true};before:=transport.calls.Load();_,err:=client.Operations.UploadCustom(sdk.UploadCustomInput{Body:itemFactory(failureStats,[]sdk.UploadCustomRequestItem{ {ID:1} })}).WithOptions(types.RequestOptions{StreamCodec:&override}).Do(context.Background());if err==nil||failureStats.closes.Load()!=1||transport.calls.Load()!=before{t.Fatal("custom encode failure ownership",err,failureStats.closes.Load())};if protocol.failure!=nil&&!errors.Is(err,sentinel){t.Fatal("custom encode cause",err)}}
}
`
